def first_non_repeating(s: str):
    """
    Return the first non-repeating character in the string.
    If the input is empty or all characters repeat, return None.
    """
    if not s:
        return None

    counts = {}

    # Count occurrences of each character
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    # Return the first character with a count of 1
    for ch in s:
        if counts[ch] == 1:
            return ch

    return None
